require 'config.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');if($action==='read_all')$pdo->exec('UPDATE notifications SET is_read=1');elseif($action==='read'){ $id=max(0,(int)($_POST['id']??0));$st=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE id=?');$st->execute([$id]);}}
